&lt;p data-path-to-node=&quot;10&quot;&gt;&lt;strong data-path-to-node=&quot;10&quot; data-index-in-node=&quot;0&quot;&gt;Essential&lt;/strong&gt;&lt;/p&gt;
&lt;ul data-path-to-node=&quot;11&quot;&gt;
